use vstd::prelude::*;

verus! {

fn smallest_num(nums: &Vec<i32>) -> (min_val: i32)
    // we assume the input vector is non‐empty
    requires
        nums.len() > 0,
    // the result is ≤ every element of the vector
    // and it actually occurs in the vector
    ensures
        forall |j: int| 0 <= j < nums.len() as int ==> min_val <= nums[j as usize],
        exists |j: int| 0 <= j < nums.len() as int && min_val == nums[j as usize],
{
    // to talk about prefixes of the vector in our invariants,
    // we first turn it into a Seq<i32>
    let seq = Seq::from_vec_ref(nums);
    let mut min_val = seq.get(0);
    let len = seq.len();
    let mut i: usize = 1;

    // we iterate over indices 1..len
    // invariant1: 1 ≤ i ≤ len
    // invariant2: for all j < i, min_val ≤ seq[j]
    // invariant3: there is some k < i with min_val == seq[k]
    // decreases: len - i
    while i < len
        invariant
            1 <= i <= len,
            forall |j: int| 0 <= j < i as int ==> min_val <= seq.get(j as usize),
            exists |k: int| 0 <= k < i as int && min_val == seq.get(k as usize),
        decreases
            len - i,
    {
        let x = seq.get(i);
        if x < min_val {
            min_val = x;
        }
        i += 1;
    }

    min_val
}

} // end verus!

